const fs = require('fs');
const path = require('path');

const cwd = __dirname;
const readme = fs.readFileSync(path.join(cwd, 'README.md'), 'utf8');

const headings = readme
  .split(/\r?\n/)
  .filter((line) => /^#/.test(line));

fs.writeFileSync(path.join(cwd, 'INDEX.md'), headings.join('\n') + '\n');

console.log(`Wrote ${headings.length} headings to INDEX.md`);

